// =============================================================================
// 场景：MES 网络抖动时可能重发同一条指令（如 "启动模具 7 号"），PLC 端
//       根据消息 GUID 去重，避免一个动作执行两次。
// 价值：跨编译器版本可靠的 GUID 等值比较；语义比 MEMCMP / 直接 = 都清晰。
// 验证步骤：
//   1. 登录后两 GUID 全 0，bIsDuplicate = FALSE。
//   2. 设置两 GUID 字段完全相同（在线写 gIncomingMesMsgId.Data1 := 16#100;
//      .Data4[0] := 16#AA; 然后同样写到 gLastProcessedMsgId）。
//   3. 写 bCheckRequest := TRUE。
//   4. 观察 bIsDuplicate = TRUE（确认是重复消息，跳过处理）。
//   5. 把 gIncomingMesMsgId.Data4[0] 改成 16#BB（其他字段不变），再触发：
//      bIsDuplicate = FALSE——印证"任何一位不同即不等"。
//   6. 把 gIncomingMesMsgId 全部清零再触发：bIsDuplicate = FALSE（因 .Data1 不同）。
// =============================================================================

IF bCheckRequest THEN
    // 单次调用：按 128 位逐字段比较
    bIsDuplicate := GuidsEqualByVal(
        guidA := gIncomingMesMsgId,
        guidB := gLastProcessedMsgId);
    bCheckRequest := FALSE;
END_IF;
